class TimeOfDay{static String now(){final d=DateTime.now();return '${d.hour.toString().padLeft(2,'0')}:${d.minute.toString().padLeft(2,'0')}:${d.second.toString().padLeft(2,'0')}';}}
String fmt(double n)=>n.abs()>=1000?n.toStringAsFixed(2):n.toStringAsFixed(4);
A analyze(List<Candle> c){final close=c.map((x)=>x.c).toList();double ema(int n){var e=close.first,k=2/(n+1);for(final p in close.skip(1))e=p*k+e*(1-k);return e;}double rsi(){var g=0.0,l=0.0;for(var i=math.max(1,close.length-14);i<close.length;i++){final d=close[i]-close[i-1];if(d>=0)g+=d;else l-=d;}return l==0?100:100-100/(1+g/l);}double atr(){var s=0.0,n=math.min(14,c.length-1);for(var i=c.length-n;i<c.length;i++)s+=math.max(c[i].h-c[i].l,math.max((c[i].h-c[i-1].c).abs(),(c[i].l-c[i-1].c).abs()));return s/math.max(1,n);}final e20=ema(20),e50=ema(50),e200=ema(200),r=rsi(),at=atr(),last=close.last,prev=close[close.length-2],last20=c.sublist(math.max(0,c.length-20)),last50=c.sublist(math.max(0,c.length-50)),hi20=last20.map((x)=>x.h).reduce(math.max),lo20=last20.map((x)=>x.l).reduce(math.min),hi50=last50.map((x)=>x.h).reduce(math.max),lo50=last50.map((x)=>x.l).reduce(math.min);final bull=e20>e50&&e50>e200&&last>e20,bear=e20<e50&&e50<e200&&last<e20,dir=bull?'LONG':bear?'SHORT':'NEUTRAL',reg=(bull||bear)?'TREND':(last>=hi20||last<=lo20?'BREAKOUT':'RANGE'),fair=e20,score=math.max(35,math.min(95,((bull||bear?72:55)+(r>55?8:r<45?-8:0)+(last>e20?7:0)).round())),buyer=math.max(5,math.min(95,(50+(r-50)*.6+(dir=='LONG'?12:dir=='SHORT'?-12:0)).round()));final pattern=last>=prev?'Bullish Price Action':'Bearish Price Action';return A(reg,dir,pattern,last,prev,r,at,e20,e50,e200,fair,hi20,lo20,hi50,lo50,score,buyer);}
class CP extends CustomPainter{final List<Candle>d;final A?a;CP(this.d,this.a);@override void paint(Canvas c,Size s){final n=math.min(100,d.length),x=d.sublist(d.length-n),hi=x.map((q)=>q.h).reduce(math.max),lo=x.map((q)=>q.l).reduce(math.min),rg=math.max(1,hi-lo),w=s.width/n,p=Paint()..strokeWidth=1;for(var y=20.0;y<s.height;y+=42){p.color=const Color(0xFF132231);c.drawLine(Offset(0,y),Offset(s.width,y),p);}double py(double v)=>15+(hi-v)/rg*(s.height-35);for(var i=0;i<n;i++){final q=x[i],px=8+i*w+w/2;p.color=q.c>=q.o?green:red;c.drawLine(Offset(px,py(q.h)),Offset(px,py(q.l)),p);final top=py(math.max(q.o,q.c)),bot=py(math.min(q.o,q.c));c.drawRect(Rect.fromLTWH(px-w*.28,top,w*.56,math.max(2,bot-top)),p);}if(a!=null){p.color=gold2;p.strokeWidth=1.2;c.drawLine(Offset(0,py(a!.fair)),Offset(s.width,py(a!.fair)),p);p.color=red;c.drawLine(Offset(0,py(a!.hi20)),Offset(s.width,py(a!.hi20)),p);p.color=blue;c.drawLine(Offset(0,py(a!.lo20)),Offset(s.width,py(a!.lo20)),p);}}@override bool shouldRepaint(covariant CP o)=>true;}
